import { Table, ReferenceColumn, StringColumn, BooleanColumn, GenericColumn } from '../../db'

export const sp_css_include = Table({
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    label: 'CSS Include',
    name: 'sp_css_include',
    schema: {
        sp_css: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Style sheet',
            referenceTable: 'sp_css',
        }),
        name: StringColumn({
            label: 'Name',
        }),
        source: StringColumn({
            default: 'local',
            choices: {
                url: {
                    label: 'URL',
                    sequence: 1,
                },
                local: {
                    label: 'Style Sheet',
                    sequence: 0,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Source',
        }),
        lazy_load: BooleanColumn({
            label: [
                {
                    hint: 'Lazy load css include',
                    label: 'Lazy Load',
                    plural: 'Lazy Loads',
                    language: 'en',
                },
            ],
        }),
        rtl_css_file_url: GenericColumn({
            columnType: 'url',
            label: [
                {
                    hint: 'If provided, this CSS file will be used when language directionality is Right to left',
                    label: 'RTL CSS file URL',
                    plural: 'RTL CSS file URLs',
                    language: 'en',
                },
            ],
            maxLength: 1024,
        }),
        url: GenericColumn({
            columnType: 'url',
            label: 'CSS file URL',
            maxLength: 1024,
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
    },
})
